-- 035 — Add 50 verbal questions
--
-- Pure insert, no passage. Ids are deterministic:
-- md5(section || '|' || prompt)::UUID with ON CONFLICT DO NOTHING, so
-- re-running this file is a no-op. Nothing existing is deleted or updated,
-- and user_question_history is never touched.

WITH q(prompt, options, correct_index, difficulty, explanation) AS (VALUES
  ('TIDY most nearly means:', '["Messy", "Neat", "Large", "Empty"]'::JSONB, 1, 1, 'Tidy describes a space that is arranged in order with nothing scattered around, and that is what neat means. Messy is the opposite of tidy, so it is the trap for anyone matching words quickly. Large and empty describe size or contents, not how orderly something is.'),
  ('HALT most nearly means:', '["Begin", "Stop", "Hurry", "Turn"]'::JSONB, 1, 1, 'To halt is to bring movement to an end, so stop is the match. Begin points the other way and catches students who are reading fast rather than thinking about direction. Hurry describes speeding up, and turn changes direction without ending the motion at all.'),
  ('AID most nearly means:', '["Harm", "Ask", "Leave", "Help"]'::JSONB, 3, 1, 'Aid means to give assistance, which is what help means. Harm points the opposite way and is the trap for a fast reader. You might ask for aid, or leave someone without it, but neither ask nor leave means giving assistance to a person.'),
  ('ODD most nearly means:', '["Strange", "Ordinary", "Round", "Fair"]'::JSONB, 0, 1, 'Odd describes something unusual or out of the ordinary, so strange is the match. Ordinary is the exact opposite, and it catches students who grab the first familiar word they see. Round describes a shape and fair describes fairness; neither one has to do with being unusual.'),
  ('VITAL most nearly means:', '["Optional", "Occasional", "Essential", "Gentle"]'::JSONB, 2, 2, 'Vital describes something you absolutely cannot do without, and essential means the same. Optional is the opposite, since an optional thing can be skipped. Occasional only tells you how often something happens, and gentle describes a manner. When a word feels this strong, look for an equally strong match.'),
  ('MOCK most nearly means:', '["Praise", "Repeat", "Compliment", "Ridicule"]'::JSONB, 3, 2, 'To mock someone is to make fun of them in a scornful way, and ridicule means the same. Praise and compliment both mean saying good things, so they run the opposite direction. Repeat tempts you because a mock version copies the real thing, but copying is not making fun.'),
  ('BLUNDER most nearly means:', '["Victory", "Mistake", "Journey", "Promise"]'::JSONB, 1, 2, 'A blunder is a clumsy, careless error, so mistake fits. Victory is the opposite kind of outcome, which makes it the choice to rule out first. A journey is a trip and a promise is a pledge; neither involves doing something wrong. Picture blundering into a room: it means stumbling.'),
  ('TENACIOUS most nearly means:', '["Frightened", "Wealthy", "Persistent", "Careless"]'::JSONB, 2, 3, 'Tenacious describes someone who holds on tightly and refuses to quit, which is what persistent means. Careless is close to the reverse, since a tenacious person is anything but casual about a goal. Frightened and wealthy describe fear and money, neither of which is staying power.'),
  ('AMPLE most nearly means:', '["Narrow", "Temporary", "Bitter", "Plentiful"]'::JSONB, 3, 3, 'Ample means more than enough, so plentiful matches. Narrow suggests too little room, and it pulls at students who link ample with size alone. Temporary is about time and bitter is about taste, so neither measures quantity. An ample serving is a generous one.'),
  ('WARY most nearly means:', '["Cautious", "Weary", "Cheerful", "Hasty"]'::JSONB, 0, 3, 'Wary means watchful because trouble might be near, so cautious is the match. Weary is the classic trap here: one letter apart, but it means tired. Hasty means rushing, which is the opposite of watching your step, and cheerful has nothing to do with caution.'),
  ('EMPTY is the opposite of:', '["Full", "Open", "Light", "Small"]'::JSONB, 0, 1, 'Empty means holding nothing at all, so its opposite is full, which means holding all it can. Open is about access rather than contents, and it tempts anyone picturing an open container. Light and small describe weight and size, and an empty box may or may not be either.'),
  ('WEAK is the opposite of:', '["Soft", "Slender", "Thin", "Strong"]'::JSONB, 3, 1, 'Weak means lacking power or force, so strong is the opposite. Thin and slender are the tempting pair, because we often picture weak people as thin, but those words describe body size and not strength. Soft describes texture. Ask what quality the word measures, then flip that quality.'),
  ('BEGIN is the opposite of:', '["Start", "End", "Try", "Open"]'::JSONB, 1, 1, 'Begin means to start something, so its opposite is end. Start is planted here on purpose: it is a synonym, and synonyms feel right when you are moving fast through an antonym section. Open and try do not reverse begin either, since neither one means finishing.'),
  ('CHEAP is the opposite of:', '["Costly", "Common", "Broken", "Simple"]'::JSONB, 0, 1, 'Cheap means low in price, so costly, meaning high in price, is the opposite. Common is the strongest trap, because cheap things often are common, but that is a pattern in the world rather than the meaning of the word. Broken and simple describe condition and difficulty.'),
  ('FRAGILE is the opposite of:', '["Delicate", "Sturdy", "Small", "Clear"]'::JSONB, 1, 2, 'Fragile means easily broken, so sturdy, meaning strongly built, is the opposite. Delicate is the planted synonym: it means nearly the same as fragile, so it can never be its antonym. Small and clear describe size and appearance, and a fragile object can be either one.'),
  ('ABSENT is the opposite of:', '["Missing", "Late", "Quiet", "Present"]'::JSONB, 3, 2, 'Absent means not here, so present is the opposite. Missing is the planted synonym, and it is easy to grab because missing and absent feel identical. Late tempts you too, but a late student still turns up, which puts late closer to present than to absent.'),
  ('RETREAT is the opposite of:', '["Withdraw", "Escape", "Advance", "Hide"]'::JSONB, 2, 2, 'To retreat is to pull back, so advance, moving forward, is the opposite. Withdraw is the synonym planted to catch you, since retreating and withdrawing are the same move. Escape and hide are other ways of getting away from something, not ways of coming forward.'),
  ('OBSCURE is the opposite of:', '["Vague", "Distant", "Clear", "Hidden"]'::JSONB, 2, 3, 'Obscure means hard to see or hard to understand, so clear is its opposite. Vague and hidden are both synonyms of obscure, planted for the student who reads at speed. Distant tells you how far away something is, which is not the same as how hard it is to make out.'),
  ('RESOLUTE is the opposite of:', '["Determined", "Wavering", "Honest", "Patient"]'::JSONB, 1, 3, 'Resolute means firmly determined, so its opposite is wavering, going back and forth. Determined is a synonym, not an opposite, and it is an easy slip when you are reading fast. Honest and patient name other good qualities, but neither reverses being firmly decided.'),
  ('NOVICE is the opposite of:', '["Beginner", "Student", "Helper", "Expert"]'::JSONB, 3, 3, 'A novice is brand new at something, so an expert, who has mastered it, is the opposite. Beginner is the planted synonym and means the same as novice. A student is usually still learning, which puts student on the novice side too, and helper describes a role instead.'),
  ('Hammer is to nail as screwdriver is to:', '["Wood", "Screw", "Toolbox", "Handle"]'::JSONB, 1, 1, 'Say the link as a sentence: a hammer is the tool made to drive a nail, so a screwdriver is the tool made to drive a screw. Wood is the material you drive a fastener into, a toolbox is where a tool is stored, and a handle is part of the tool itself.'),
  ('Baker is to bread as farmer is to:', '["Tractor", "Barn", "Crops", "Field"]'::JSONB, 2, 1, 'A baker makes bread, so the link is worker to product, and a farmer makes crops. Tractor tempts you because farmers use tractors, but a tractor is equipment, like the baker''s oven, not the thing produced. A barn and a field are places where the work happens.'),
  ('Big is to small as heavy is to:', '["Weight", "Large", "Solid", "Light"]'::JSONB, 3, 1, 'Big and small are opposites, so the second pair must be opposites too: heavy and light. Weight is the category these words belong to rather than an opposite, and it tempts students who match by topic. Large is a synonym of big, and solid describes firmness, not heaviness.'),
  ('Thermometer is to temperature as scale is to:', '["Weight", "Height", "Time", "Speed"]'::JSONB, 0, 2, 'A thermometer is the instrument that measures temperature, so a scale is the instrument that measures weight. Height, time, and speed are all things that get measured, which makes them feel right, but each one needs its own instrument: a ruler, a clock, a speedometer.'),
  ('Pebble is to boulder as puddle is to:', '["Rain", "Lake", "Mud", "Cloud"]'::JSONB, 1, 2, 'A pebble is a tiny version of a boulder, so the link is small to large inside one category, and a puddle is a tiny version of a lake. Rain and cloud are where the water comes from rather than larger amounts of standing water, and mud is a different substance.'),
  ('Deafening is to loud as scorching is to:', '["Cold", "Dry", "Hot", "Bright"]'::JSONB, 2, 2, 'Deafening is loud taken to an extreme, so the link is intensity, and scorching is hot taken to an extreme. Cold reverses the idea instead of intensifying it, which is why it draws guesses. Bright and dry name other qualities that heat often comes with but does not mean.'),
  ('Miser is to money as glutton is to:', '["Hunger", "Weight", "Manners", "Food"]'::JSONB, 3, 3, 'A miser is defined by an extreme relationship to money, so a glutton is defined by an extreme relationship to food. Hunger is the feeling behind overeating, not the thing overeaten, and weight is a possible result. Manners are what a glutton lacks, but the pattern calls for the object.'),
  ('Skeptic is to doubt as optimist is to:', '["Fear", "Hope", "Anger", "Sorrow"]'::JSONB, 1, 3, 'Each word names the attitude that defines the person: a skeptic is defined by doubt, and an optimist is defined by hope. Fear, anger, and sorrow are real emotions, but none of them is what makes someone an optimist. Build the sentence first, then test every choice inside it.'),
  ('Apprentice is to master as sapling is to:', '["Seed", "Leaf", "Tree", "Forest"]'::JSONB, 2, 3, 'An apprentice is the early stage that grows into a master, so the link runs from immature form to mature form, and a sapling grows into a tree. Seed is the tempting choice, but a seed comes before the sapling rather than after it. A leaf is a part and a forest is a group.'),
  ('Confident is to arrogant as thrifty is to:', '["Bashful", "Trustworthy", "Stingy", "Wealthy"]'::JSONB, 2, 3, 'Arrogant is confidence pushed past the healthy point, so the link is a good trait carried to an unpleasant excess, and thriftiness carried too far becomes stingy. Wealthy describes how much money you have, not how you handle it, and bashful and trustworthy are unrelated traits.'),
  ('All whales are mammals. Shamu is a whale. Shamu is a mammal — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 0, 1, 'In these questions you accept the premises as given and only test the conclusion. Every whale belongs to the group of mammals, and Shamu is named as a whale, so Shamu must be a mammal. That makes the conclusion true, not false. Choose uncertain only when the premises leave a real gap.'),
  ('No bicycles have engines. This vehicle has an engine. This vehicle is a bicycle — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 1, 1, 'The word no is absolute: if no bicycle has an engine, then nothing with an engine can be a bicycle. This vehicle has an engine, so the conclusion is false rather than true. Uncertain is the popular guess, but once a rule covers every case, nothing is left unknown.'),
  ('Some birds are blue. Pico is a bird. Pico is blue — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 2, 1, 'Some means at least one, not all. Knowing that Pico is a bird does not tell you whether he sits inside the blue group or outside it, so the answer is uncertain. True would require all birds to be blue, and false would require that no bird is blue.'),
  ('Some jars in the pantry are empty. All jars in the pantry are glass. Some glass jars are empty — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 0, 2, 'Follow the chain. The empty jars are pantry jars, and every pantry jar is glass, so those same empty jars are glass jars, which makes the conclusion true rather than false. Uncertain tempts you because the word some feels shaky, but some combined with all still guarantees an overlap.'),
  ('No mushrooms are plants. Some fungi are mushrooms. All fungi are plants — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 1, 2, 'Some fungi are mushrooms, and no mushroom is a plant, so at least some fungi are definitely not plants. A claim that starts with all is broken by even one exception, so this one is false and cannot be true. Uncertain would fit only if the premises told you nothing about fungi.'),
  ('All lifeguards can swim. Some campers can swim. Some campers are lifeguards — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 2, 2, 'The premises say all lifeguards can swim, not that all swimmers are lifeguards. The campers who swim might all be ordinary campers, or some might be lifeguards, and nothing tells you which, so the answer is uncertain. True would need proof of an overlap, and false would need proof there is none.'),
  ('Some volunteers are nurses. All nurses are trained in first aid. Some volunteers are trained in first aid — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 0, 3, 'Chain the facts together. The volunteers who are nurses are covered by the rule that every nurse is trained in first aid, so at least some volunteers are trained. That is exactly what the conclusion claims, so it is true, not false. Uncertain tempts you only because of the word some.'),
  ('All winners of the science fair built a model. No one who built a model used a kit. Some winners used a kit — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 1, 3, 'Link them: every winner built a model, and nobody who built a model used a kit, so no winner could have used one. The claim that some winners did is false and cannot be true. Uncertain feels safer because of the word some, but the premises cover all of the winners.'),
  ('Every guitarist in the band reads music. Some members of the band do not read music. Some members of the band are not guitarists — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 0, 3, 'Turn the rule around. Since every guitarist reads music, anyone who cannot read music is not a guitarist. Some band members cannot read music, so those members are not guitarists, which makes the conclusion true rather than false or uncertain. A negative fact can prove something for certain.'),
  ('Some athletes are vegetarians. Some vegetarians are chefs. Some athletes are chefs — true, false, or uncertain?', '["True", "False", "Uncertain", "Neither"]'::JSONB, 2, 3, 'Two statements that both begin with some almost never combine. The vegetarians who are athletes and the vegetarians who are chefs could be completely different people, so the answer is uncertain. True would require a proven overlap and false would require proof of none, and the premises give neither.'),
  ('Which word does NOT belong with the others: Rain, Cloud, Snow, Sleet?', '["Rain", "Cloud", "Snow", "Sleet"]'::JSONB, 1, 1, 'Rain, snow, and sleet are all precipitation: water that falls from the sky to the ground. A cloud is made of water too, which is why it feels like it belongs, but it stays up in the sky instead of falling. Name the shared property first, then find what lacks it.'),
  ('Which word does NOT belong with the others: Cube, Circle, Square, Triangle?', '["Cube", "Circle", "Square", "Triangle"]'::JSONB, 0, 1, 'Circle, square, and triangle are flat two-dimensional shapes you can draw on paper. A cube is a solid with depth, so it does not fit. Square is the tempting pick because a cube is built out of squares, but being related to the group is not the same as sharing its property.'),
  ('Which word does NOT belong with the others: Nurse, Doctor, Clinic, Dentist?', '["Nurse", "Doctor", "Clinic", "Dentist"]'::JSONB, 2, 1, 'Nurse, doctor, and dentist all name people who work in health care. A clinic is the building where that work happens, so it is the odd one out. It sits in the same topic, and that is exactly the trap: a shared subject is not the same as a shared category.'),
  ('Which word does NOT belong with the others: Salmon, Trout, Mackerel, Dolphin?', '["Salmon", "Trout", "Mackerel", "Dolphin"]'::JSONB, 3, 2, 'Salmon, trout, and mackerel are fish, which breathe through gills. A dolphin swims in the ocean right alongside them, but it is a mammal that surfaces to breathe air. Where an animal lives is not the same as what it is, and that difference is what this question is testing.'),
  ('Which word does NOT belong with the others: Mile, Ounce, Pound, Ton?', '["Mile", "Ounce", "Pound", "Ton"]'::JSONB, 0, 2, 'Ounce, pound, and ton all measure weight, and they even scale up in order, which makes the group easy to spot. A mile is a unit too, but it measures distance. Ask what quality each unit measures, rather than whether it is a unit at all.'),
  ('Which word does NOT belong with the others: Praise, Insult, Compliment, Flatter?', '["Praise", "Insult", "Compliment", "Flatter"]'::JSONB, 1, 2, 'Praise, compliment, and flatter all mean saying approving things about someone. To insult is to do the opposite, so it is the word that does not belong. Flatter is the tempting pick because flattery can be insincere, but even insincere praise is still praise, so it stays with the group.'),
  ('Which word does NOT belong with the others: Sonnet, Haiku, Ballad, Novel?', '["Sonnet", "Haiku", "Ballad", "Novel"]'::JSONB, 3, 3, 'A sonnet, a haiku, and a ballad are all poems, each with its own form and rhythm. A novel is a long story told in prose. Ballad draws guesses because ballads are often sung, but a ballad is still a poem set to music, so it belongs with the others.'),
  ('Which word does NOT belong with the others: Thrifty, Wasteful, Economical, Frugal?', '["Thrifty", "Wasteful", "Economical", "Frugal"]'::JSONB, 1, 3, 'Thrifty, economical, and frugal all describe someone careful with money or resources. Wasteful describes the opposite habit. All four words involve money, which makes the topic feel shared, and that is the trap: this group is defined by carefulness, not by the subject of money.'),
  ('Which word does NOT belong with the others: Ocean, Peninsula, Island, Isthmus?', '["Ocean", "Peninsula", "Island", "Isthmus"]'::JSONB, 0, 3, 'A peninsula, an island, and an isthmus are all landforms shaped by the water around them. The ocean is that water itself, not a piece of land, so it is the odd one out. Water appears in every definition here, which is why the ocean can feel like part of the group.'),
  ('Which word does NOT belong with the others: Biography, Diary, Fable, Memoir?', '["Biography", "Diary", "Fable", "Memoir"]'::JSONB, 2, 3, 'A biography, a diary, and a memoir all record things that really happened in a real person''s life. A fable is an invented story, usually with animals and a moral. Biography and memoir are easy to confuse with each other, but both are true accounts, so neither one is the outlier.')
)
INSERT INTO questions (id, section, passage, prompt, options, correct_index, difficulty, explanation)
SELECT md5('verbal' || '|' || q.prompt)::UUID, 'verbal'::section_type, NULL,
       q.prompt, q.options, q.correct_index, q.difficulty, q.explanation
FROM q
ON CONFLICT (id) DO NOTHING;

